-- Rehearsal body for PROPOSAL_founder_ownership_and_unlink.sql. Runs inside ONE transaction that rehearse_finance_stamp.sh ROLLS BACK. Local scratch database only. Synthetic users/entities.
-- Every check raises an exception on failure; the script stops at the first one (ON_ERROR_STOP).
set session_replication_role = replica;
insert into auth.users (id, email) select ('00000000-0000-4000-8000-0000000000'||lpad(to_hex(n),2,'0'))::uuid, 'f'||n||'@e2e.test' from generate_series(240,243) n on conflict do nothing;
insert into public.profiles (id, full_name, access_status) select ('00000000-0000-4000-8000-0000000000'||lpad(to_hex(n),2,'0'))::uuid, 'Fin '||n, 'active' from generate_series(240,243) n on conflict do nothing;
insert into public.user_roles (user_id, role_id) select '00000000-0000-4000-8000-0000000000f0', r.id from public.roles r where r.slug = 'super_admin' on conflict do nothing;      -- f0 = 240: Super Admin
insert into public.user_roles (user_id, role_id) select '00000000-0000-4000-8000-0000000000f1', r.id from public.roles r where r.slug = 'admin' on conflict do nothing;            -- f1 = 241: ordinary admin
insert into public.employing_entities (id, name, slug, legal_name, verification_status) values
  ('11111111-1111-4111-8111-111111111101', 'Fin Entity A', 'fin-a', 'FIN ENTITY A W.L.L.', 'verified'), ('11111111-1111-4111-8111-111111111102', 'Fin Entity B', 'fin-b', 'FIN ENTITY B W.L.L.', 'verified') on conflict do nothing;
insert into public.employing_entity_documents (id, employing_entity_id, document_type, storage_path, uploaded_by, file_sha256, original_filename, mime_type, size_bytes) values
  ('22222222-2222-4222-8222-222222222201', '11111111-1111-4111-8111-111111111101', 'purchase_receipt', 'a/inv.jpg', '00000000-0000-4000-8000-0000000000f0', repeat('a', 64), 'invoice.jpg', 'image/jpeg', 1000),
  ('22222222-2222-4222-8222-222222222202', '11111111-1111-4111-8111-111111111101', 'other_financial_document', 'a/pl.pdf', '00000000-0000-4000-8000-0000000000f0', repeat('b', 64), 'receipt_SQ1.pdf', 'application/pdf', 2000),
  ('22222222-2222-4222-8222-222222222203', '11111111-1111-4111-8111-111111111102', 'other_financial_document', 'b/pl.pdf', '00000000-0000-4000-8000-0000000000f0', repeat('c', 64), 'other_entity.pdf', 'application/pdf', 2000),
  ('22222222-2222-4222-8222-222222222204', '11111111-1111-4111-8111-111111111101', 'other_financial_document', 'a/bank.pdf', '00000000-0000-4000-8000-0000000000f0', repeat('d', 64), 'statement.pdf', 'application/pdf', 3000)
  on conflict do nothing;
set session_replication_role = origin;
insert into public.employing_entity_documents (id, employing_entity_id, document_type, storage_path, uploaded_by, file_sha256, original_filename, mime_type, size_bytes) values
  ('22222222-2222-4222-8222-222222222205', '11111111-1111-4111-8111-111111111102', 'purchase_receipt', 'b/inv.jpg', '00000000-0000-4000-8000-0000000000f0', repeat('e', 64), 'ghana-invoice.jpg', 'image/jpeg', 1000) on conflict do nothing;
-- the Founder identity (lab only, inside the rolled-back transaction): the synthetic Super Admin f0 is the ACTIVE Founder
set session_replication_role = replica; delete from public.founder_identities;
insert into public.founder_identities (profile_id, status, designation_reference) values ('00000000-0000-4000-8000-0000000000f0', 'active', 'Rehearsal Founder designation reference (synthetic)'); set session_replication_role = origin;
create or replace function pg_temp.err(q text) returns text language plpgsql as $$ begin execute q; return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.must(cond boolean, msg text) returns void language plpgsql as $$ begin if not coalesce(cond, false) then raise exception 'REHEARSAL FAILED: %', msg; end if; end $$;
create temp table t_ids (name text primary key, id uuid); grant all on t_ids to public;
create or replace function pg_temp.mk(inv text, fund text, ent uuid default '11111111-1111-4111-8111-111111111101') returns uuid language plpgsql as $$
declare r record;
begin select * into r from public.record_equipment_acquisition(jsonb_build_object('entityId', ent, 'acquisition', jsonb_build_object('supplier','Synthetic Supplier','invoiceNumber',inv,'purchaseDate','2026-11-01','itemDescription','Synthetic pen display','quantity',1,'currency','QAR','listPrice',1149,'discount',0,'net',1149,
  'invoiceDocumentId', case when ent = '11111111-1111-4111-8111-111111111101' then '22222222-2222-4222-8222-222222222201' else '22222222-2222-4222-8222-222222222205' end,'fundingStatus',fund,'fundingNote','Founder statement: company card')), '00000000-0000-4000-8000-0000000000f0'); return r.acquisition_id; end $$;
insert into public.company_assets (id, asset_identifier, description, category) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01', 'SER-Q', 'Synthetic Qatar pen display', 'Pad'), ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02', 'SER-L', 'Synthetic legal-entity item', 'Other'), ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa03', 'SER-G', 'Synthetic Ghana item', 'Other');
create temp table t_before as select (select md5(string_agg(row_to_json(a)::text, '|' order by a.id)) from public.company_assets a) assets_h, (select md5(coalesce(string_agg(row_to_json(x)::text, '|' order by x.id), '')) from public.asset_assignments x) assign_h,
  (select md5(string_agg(row_to_json(d)::text, '|' order by d.id)) from public.employing_entity_documents d) vault_h;
insert into t_ids values ('q_funded', pg_temp.mk('Q-1', 'company_account')), ('q_tbc', pg_temp.mk('Q-2', 'to_confirm')), ('g_funded', pg_temp.mk('G-1', 'company_account', '11111111-1111-4111-8111-111111111102'));
create or replace function pg_temp.i(n text) returns uuid language sql as $$ select id from t_ids where name = n $$;
create or replace function pg_temp.fo(asset uuid, ent uuid, basis text default 'Founder statement: personally owned; payments funded with the company card; treatment pending', funded boolean default true, actor uuid default '00000000-0000-4000-8000-0000000000f0') returns text language plpgsql as $$
begin perform public.record_founder_asset_ownership(asset, ent, 'The Founder, as printed on the receipt', 'The Founder', 'The Founder (personal PayLater account)', 'Photography retouching and related creative production', funded, basis, null, actor); return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.lnk(acq uuid, asset uuid) returns text language plpgsql as $$ begin perform public.link_acquisition_to_asset(acq, asset, '00000000-0000-4000-8000-0000000000f0'); return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.unl(acq uuid, reason text, actor uuid default '00000000-0000-4000-8000-0000000000f0') returns text language plpgsql as $$ begin perform public.unlink_acquisition_from_asset(acq, reason, actor); return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.linked(acq uuid) returns uuid language sql as $$ select company_asset_id from public.entity_equipment_acquisitions where id = acq $$;
-- 1. 0188 objects unchanged by 0189 (constraints other than the new one, indexes, policies, grants, function privileges)
select pg_temp.must((select c from t_snap) = (select md5(string_agg(conname || pg_get_constraintdef(oid), '|' order by conname)) from pg_constraint where conrelid = 'public.entity_asset_ownership'::regclass and conname <> 'ownership_kind_shape' and conname not like '%owner_kind%' and conname not like '%primary_user%' and conname not like '%obligor%' and conname not like '%owner_profile%'), 'the 0188 constraints on the ownership table are unchanged');
select pg_temp.must((select i from t_snap) = (select md5(string_agg(indexdef, '|' order by indexname)) from pg_indexes where schemaname = 'public' and tablename in ('entity_asset_ownership', 'entity_equipment_acquisitions')), 'the 0188 indexes are unchanged');
select pg_temp.must((select p from t_snap) = (select md5(string_agg(policyname || cmd || qual::text, '|' order by policyname)) from pg_policies where tablename = 'entity_asset_ownership'), 'the ownership policies are unchanged');
select pg_temp.must((select g from t_snap) = (select md5(string_agg(grantee || privilege_type, '|' order by grantee, privilege_type)) from information_schema.role_table_grants where table_name = 'entity_asset_ownership'), 'the ownership table grants are unchanged');
select pg_temp.must((select f from t_snap) = (select md5(string_agg(a || b || c, '|' order by a)) from (select proname a, has_function_privilege('service_role', oid, 'execute')::text b, (has_function_privilege('authenticated', oid, 'execute') or has_function_privilege('anon', oid, 'execute'))::text c from pg_proc where pronamespace = 'public'::regnamespace and proname in ('record_asset_ownership', 'void_asset_ownership', 'link_acquisition_to_asset')) z), 'the 0188 function privileges are unchanged');
-- 2. Founder-personal ownership (Qatar records): distinct type, active Founder only, flags, pending review
select pg_temp.must(pg_temp.fo('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01', '11111111-1111-4111-8111-111111111101', 'too short') ilike '%at least 20 characters%', 'the basis must be substantive');
select pg_temp.must(pg_temp.fo('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01', '11111111-1111-4111-8111-111111111101', actor => '00000000-0000-4000-8000-0000000000f1') ilike '%only a Super Admin%', 'an ordinary admin cannot record ownership');
select pg_temp.must(pg_temp.fo('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01', '11111111-1111-4111-8111-111111111101') = '', 'Founder-personal ownership recorded (filed under the Qatar entity)');
select pg_temp.must((select owner_kind || '|' || (owner_profile_id = '00000000-0000-4000-8000-0000000000f0')::text || '|' || company_funded::text || '|' || excluded_from_company_fixed_assets::text || '|' || review_status from public.entity_asset_ownership where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') = 'founder_personal|true|true|true|pending_professional_review', 'personal owner = the active Founder; company-funded flag set; excluded from company fixed assets; pending professional review');
select pg_temp.must((select primary_user_as_stated from public.entity_asset_ownership where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') = 'The Founder' and (select financing_obligor_as_stated from public.entity_asset_ownership where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') ilike '%personal PayLater%' and (select purchaser_as_stated from public.entity_asset_ownership where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') ilike '%printed on the receipt%', 'purchaser, user and financing obligor are stated separately from the owner');
select pg_temp.must(pg_temp.err($q$insert into public.entity_asset_ownership (employing_entity_id, asset_id, business_purpose, basis_statement, recorded_by, owner_kind, owner_profile_id) values ('11111111-1111-4111-8111-111111111101', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02', 'Synthetic business purpose text', 'Synthetic basis statement text', '00000000-0000-4000-8000-0000000000f0', 'founder_personal', '00000000-0000-4000-8000-0000000000f1')$q$) ilike '%ACTIVE Founder identity%', 'a personal owner other than the active Founder is refused (even by a direct insert)');
select pg_temp.must(pg_temp.err($q$insert into public.entity_asset_ownership (employing_entity_id, asset_id, business_purpose, basis_statement, recorded_by, owner_kind, owner_profile_id) values ('11111111-1111-4111-8111-111111111101', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02', 'Synthetic business purpose text', 'Synthetic basis statement text', '00000000-0000-4000-8000-0000000000f0', 'legal_entity', '00000000-0000-4000-8000-0000000000f0')$q$) ilike '%ownership_kind_shape%', 'a legal-entity owner carries no personal profile');
select pg_temp.must(pg_temp.err($q$insert into public.entity_asset_ownership (employing_entity_id, asset_id, business_purpose, basis_statement, recorded_by, company_funded) values ('11111111-1111-4111-8111-111111111101', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02', 'Synthetic business purpose text', 'Synthetic basis statement text', '00000000-0000-4000-8000-0000000000f0', true)$q$) ilike '%ownership_kind_shape%', 'the company-funded personal-asset flag exists only for personal ownership');
select pg_temp.must(pg_temp.err($q$update public.entity_asset_ownership set owner_kind = 'legal_entity', owner_profile_id = null, company_funded = false where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01'$q$) ilike '%cannot be edited%', 'the ownership type, owner and flags cannot be edited');
select pg_temp.must(pg_temp.err($q$update public.entity_asset_ownership set excluded_from_company_fixed_assets = false$q$) ilike '%can only be updated to DEFAULT%', 'the fixed-asset exclusion is a generated column and cannot be switched off');
-- 3. legal-entity ownership still works exactly as in 0188 (and is NOT excluded)
select pg_temp.must((select count(*) from (select public.record_asset_ownership('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02', '11111111-1111-4111-8111-111111111101', 'The Founder', 'Photography retouching and graphic design for the company', false, null, 'Founder statement: bought for the company; documents pending', null, '00000000-0000-4000-8000-0000000000f0')) z) = 1, 'legal-entity ownership still recorded through the 0188 function');
select pg_temp.must((select owner_kind || '|' || excluded_from_company_fixed_assets::text from public.entity_asset_ownership where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02') = 'legal_entity|false', 'a legal-entity owner is a different type and is not excluded');
-- 4. Qatar / Ghana separation
select pg_temp.must(pg_temp.fo('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa03', '11111111-1111-4111-8111-111111111102') = '', 'Ghana scenario: Founder-personal ownership filed under the GHANA entity');
select pg_temp.must(pg_temp.lnk(pg_temp.i('g_funded'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') ilike '%THIS legal entity%', 'a Ghana acquisition cannot link to an asset filed under the Qatar entity');
select pg_temp.must(pg_temp.lnk(pg_temp.i('q_funded'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa03') ilike '%THIS legal entity%', 'a Qatar acquisition cannot link to an asset filed under the Ghana entity');
select pg_temp.must(pg_temp.lnk(pg_temp.i('g_funded'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa03') = '', 'the Ghana acquisition links to the Ghana-filed asset');
-- 5. linking rules for personal ownership
select pg_temp.must(pg_temp.lnk(pg_temp.i('q_tbc'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') ilike '%funding source is stated%', 'a Founder-owned asset links only to an acquisition whose funding source is stated');
select pg_temp.must(pg_temp.lnk(pg_temp.i('q_funded'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') = '', 'the funded Qatar acquisition links to the Founder-owned asset');
select pg_temp.must(pg_temp.lnk(pg_temp.i('q_tbc'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') ilike '%acquisitions_one_per_asset%' or pg_temp.lnk(pg_temp.i('q_tbc'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') ilike '%funding source is stated%', 'no second acquisition for the same asset');
select pg_temp.must(pg_temp.err(format($q$select public.void_asset_ownership(%L, 'recorded against the wrong asset by mistake', '00000000-0000-4000-8000-0000000000f0')$q$, (select id from public.entity_asset_ownership where asset_id = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01'))) ilike '%acquisition is linked%', 'ownership cannot be voided while linked (0188 rule unchanged)');
-- 6. audited unlink: mandatory reason, no silent rewrite, immutable history
select pg_temp.must(pg_temp.err($q$update public.entity_equipment_acquisitions set company_asset_id = null where invoice_number = 'Q-1'$q$) ilike '%cannot be changed or cleared%', 'a direct update still cannot clear or change a link');
select pg_temp.must(pg_temp.unl(pg_temp.i('q_funded'), 'short') ilike '%reason%', 'unlink needs a written reason');
select pg_temp.must(pg_temp.unl(pg_temp.i('q_funded'), 'the accountant concluded a different structure', '00000000-0000-4000-8000-0000000000f1') ilike '%only a Super Admin%', 'an ordinary admin cannot unlink');
select pg_temp.must(pg_temp.unl(pg_temp.i('q_tbc'), 'not linked, so nothing to unlink here') ilike '%not linked%', 'an unlinked acquisition cannot be unlinked');
select pg_temp.must(pg_temp.unl(pg_temp.i('q_funded'), 'the accountant concluded a different structure') = '', 'the audited unlink succeeds with a reason');
select pg_temp.must(pg_temp.linked(pg_temp.i('q_funded')) is null, 'the link is cleared');
select pg_temp.must((select count(*) from public.entity_finance_events where event_type = 'asset_linked' and acquisition_id = pg_temp.i('q_funded')) = 1 and (select detail ->> 'reason' from public.entity_finance_events where event_type = 'asset_unlinked' and acquisition_id = pg_temp.i('q_funded')) = 'the accountant concluded a different structure', 'history kept: the original link event stays and the unlink event records the reason');
select pg_temp.must(pg_temp.err($q$update public.entity_finance_events set detail = '{}' where event_type = 'asset_unlinked'$q$) ilike '%append-only%' and pg_temp.err($q$delete from public.entity_finance_events where event_type = 'asset_linked'$q$) ilike '%append-only%', 'the link history cannot be rewritten or deleted');
select pg_temp.must(pg_temp.lnk(pg_temp.i('q_funded'), 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa01') = '', 're-linking after an unlink works and is audited again');
select pg_temp.must((select count(*) from public.entity_finance_events where event_type = 'asset_linked' and acquisition_id = pg_temp.i('q_funded')) = 2, 'two link events and one unlink event are all retained');
-- 7. no duplicates or accounting side effects; register, custody and vault unchanged; no active Founder identity => refused
select pg_temp.must((select count(*) from public.company_assets) = 3 and (select count(*) from public.entity_equipment_acquisitions) = 3 and (select count(*) from public.entity_financing_obligations) = 0 and (select count(*) from public.entity_acquisition_payments) = 0 and (select count(*) from public.entity_expenses) = 0, 'no duplicate asset, acquisition, financing obligation, payment or expense was created');
select pg_temp.must((select assets_h from t_before) = (select md5(string_agg(row_to_json(a)::text, '|' order by a.id)) from public.company_assets a) and (select assign_h from t_before) = (select md5(coalesce(string_agg(row_to_json(x)::text, '|' order by x.id), '')) from public.asset_assignments x) and (select vault_h from t_before) = (select md5(string_agg(row_to_json(d)::text, '|' order by d.id)) from public.employing_entity_documents d), 'asset register, custody records and vault documents are byte-identical');
select pg_temp.must(not has_function_privilege('authenticated', 'public.unlink_acquisition_from_asset(uuid, text, uuid)', 'execute') and not has_function_privilege('anon', 'public.record_founder_asset_ownership(uuid, uuid, text, text, text, text, boolean, text, uuid, uuid)', 'execute') and has_function_privilege('service_role', 'public.unlink_acquisition_from_asset(uuid, text, uuid)', 'execute'), 'the two new functions are service_role-only');
set session_replication_role = replica; update public.founder_identities set status = 'revoked', revoked_at = now(), revoked_reason = 'rehearsal: no active Founder identity' where status = 'active'; set session_replication_role = origin;
select pg_temp.must(pg_temp.fo('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaa02', '11111111-1111-4111-8111-111111111101') ilike '%no active Founder identity%', 'without an active Founder identity no personal ownership can be recorded');
select 'FOUNDER OWNERSHIP REHEARSAL PASSED' as result;
